"""Plan and section diagram of the lift, the 2x2 m anteroom and the control room west door, drawn from the same constants as cr_lift.py.
usage: python cr_lift_diagram.py -- <out.png>      (needs matplotlib; pip install matplotlib in the Blender python)"""
import sys
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle, Circle, FancyArrowPatch
OUT=sys.argv[sys.argv.index("--")+1]
fig=plt.figure(figsize=(18,10),dpi=100); axp=fig.add_axes([0.03,0.07,0.60,0.86]); axs=fig.add_axes([0.67,0.12,0.30,0.76])
def R(ax,x0,x1,y0,y1,fc,ec="#222",lw=1.0,ls="-",z=2,alpha=1.0,hatch=None): ax.add_patch(Rectangle((x0,y0),x1-x0,y1-y0,fc=fc,ec=ec,lw=lw,ls=ls,zorder=z,alpha=alpha,hatch=hatch))
def T(ax,x,y,s,size=9,c="#111",ha="center",va="center",w="normal",z=9): ax.text(x,y,s,fontsize=size,color=c,ha=ha,va=va,fontweight=w,zorder=z)
def A(ax,p,q,c="#c0392b",lw=2.4,style="-|>",z=8,ls="-"): ax.add_patch(FancyArrowPatch(p,q,arrowstyle=style,mutation_scale=16,color=c,lw=lw,zorder=z,linestyle=ls))
# ------------------------------------------------------------------ plan (top view)
ax=axp; ax.set_aspect("equal"); ax.set_xlim(-10.4,-2.6); ax.set_ylim(-8.9,-3.3); ax.set_facecolor("#dfe6df")
ax.set_title("PLAN (top view)   +x east, +y north (reactor hall side)   metres",fontsize=13,loc="left",fontweight="bold")
T(ax,-6.0,-3.6,"REACTOR HALL  (floor 0 m)   the control-room window looks north over it",11,"#4c6a55")
R(ax,-4.8,2.0,-11.91,-6.16,"#ece5d4",ec="#222",lw=2.2,z=2); T(ax,-3.45,-8.4,"CONTROL ROOM (floor +5.4 m)",9,"#555",ha="right")
ax.plot([-4.8,2.0],[-6.10,-6.10],color="#3b7ea1",lw=6,zorder=5,solid_capstyle="butt"); T(ax,-3.3,-5.85,"window (clear glass)",8,"#2b6a8d")
R(ax,-4.83,-4.77,-7.26,-6.34,"#f4f1ea",ec="none",z=6); ax.plot([-4.80,-4.80],[-7.26,-6.34],color="#c0392b",lw=3,zorder=7); T(ax,-3.6,-6.55,"door leaf (open)",7,"#c0392b")
R(ax,-6.83,-4.80,-7.82,-5.58,"none",ec="#555",lw=1.2,ls="--",z=3); T(ax,-5.8,-8.00,"anteroom base: steel frame + solid skirt panels (z 0 to 5.2 m)",7,"#444")
R(ax,-6.83,-4.83,-7.70,-5.70,"#f2e3b3",ec="#222",lw=2.4,z=3); T(ax,-5.83,-6.50,"ANTEROOM\n2 x 2 m",9,"#7a5b00",w="bold")
R(ax,-6.28,-5.94,-6.08,-5.70,"#fff",ec="#222",lw=1.2,z=5); Circle((-6.11,-5.89),0.135); ax.add_patch(Circle((-6.11,-5.89),0.135,fc="#2f6fb5",ec="#123",zorder=6)); T(ax,-6.55,-5.12,"water cooler\n+ 19 l jug",8,z=10); ax.plot([-6.45,-6.20],[-5.30,-5.78],color="#333",lw=0.8,zorder=9)
R(ax,-6.60,-5.45,-7.70,-6.92,"#6b6b63",ec="#222",lw=1.2,z=5); T(ax,-6.02,-7.31,"loveseat",8,"#fff")
ax.add_patch(Circle((-5.22,-6.02),0.2,fc="#b5532a",ec="#222",zorder=5)); ax.add_patch(Circle((-5.22,-6.02),0.17,fc="#3c8a3c",ec="none",zorder=6)); T(ax,-5.00,-5.12,"potted plant",8,z=10); ax.plot([-5.05,-5.20],[-5.25,-5.83],color="#333",lw=0.8,zorder=9)
ax.plot([-5.83],[-6.95],marker="s",color="#f0b429",ms=9,zorder=7)
R(ax,-9.07,-6.83,-7.52,-5.28,"#9aa3a8",ec="#222",lw=2.6,z=3); T(ax,-8.0,-7.72,"LIFT SHAFT (solid enclosure)",9,"#333",w="bold")
R(ax,-8.70,-7.20,-7.15,-5.65,"#e7e7e7",ec="#222",lw=1.4,z=4); T(ax,-7.95,-6.40,"CAR\n1.5 x 1.5 m",9)
R(ax,-8.40,-7.50,-7.24,-7.12,"#555",ec="#222",z=4); T(ax,-7.45,-7.18,"counterweight",6.5,"#fff",ha="left")
ax.plot([-8.55,-7.35],[-5.28,-5.28],color="#2e8b57",lw=7,zorder=6,solid_capstyle="butt"); T(ax,-9.6,-4.85,"GROUND DOOR (north), the only opening\nonto the hall",9,"#1d6b3f",w="bold",ha="left")
ax.plot([-6.83,-6.83],[-7.0,-5.8],color="#c0392b",lw=7,zorder=6,solid_capstyle="butt"); T(ax,-8.4,-6.75,"upper door (east) ->",7.5,"#c0392b",ha="left",w="bold")
ax.plot([-4.83,-4.83],[-7.26,-6.34],color="#c0392b",lw=7,zorder=6,solid_capstyle="butt")
# route
A(ax,(-7.95,-4.2),(-7.95,-5.05),c="#2e8b57"); T(ax,-9.4,-4.25,"1  walk in from the hall",9,"#1d6b3f",ha="left")
T(ax,-8.95,-6.05,"2  ride up 5.4 m",8,"#555",ha="left")
A(ax,(-7.55,-6.42),(-6.95,-6.42),c="#c0392b"); A(ax,(-6.80,-6.42),(-5.30,-6.80),c="#c0392b"); A(ax,(-5.05,-6.82),(-3.5,-6.82),c="#c0392b")
T(ax,-4.55,-7.45,"3  exit east, cross the\nanteroom, through the\ncontrol-room door",8,"#c0392b",ha="left")
# compass + scale
A(ax,(-2.9,-4.6),(-2.9,-3.9),c="#222",lw=2.0); T(ax,-2.9,-3.7,"N",11,w="bold"); R(ax,-10.2,-8.2,-8.75,-8.72,"#222",ec="#222",z=9); T(ax,-9.2,-8.6,"2 m",8)
T(ax,-2.7,-8.8,"Plan from cr_lift.py. Shaft interior x -8.95..-6.95, y -7.40..-5.40; anteroom interior x -6.83..-4.83, y -7.70..-5.70.",7.5,"#666",ha="right")
# ------------------------------------------------------------------ section along y = -6.4 (west to east)
ax=axs; ax.set_xlim(-9.6,-3.6); ax.set_ylim(-0.6,11.4); ax.set_aspect("equal"); ax.set_facecolor("#f4f1ea")
ax.set_title("SECTION along y = -6.4  (west to east)   metres",fontsize=13,loc="left",fontweight="bold")
R(ax,-9.6,-3.6,-0.6,0.0,"#c9c3b2",ec="none",z=0); T(ax,-4.2,-0.3,"hall floor 0 m",8)
R(ax,-9.07,-6.83,0.0,10.95,"#9aa3a8",ec="#222",lw=2,z=1,alpha=0.45); T(ax,-7.95,10.25,"shaft top / machine room",7.5)
for z0,lab in ((0.0,"car at GROUND (t = 0 to 5 s)"),(5.4,"car at UPPER (t = 11 to 17 s)")):
    R(ax,-8.70,-7.20,z0,z0+2.48,"#e7e7e7",ec="#222",lw=1.6,z=4,alpha=0.9); T(ax,-7.95,z0+1.2,lab.split(" (")[0]+"\n"+"("+lab.split(" (")[1],8)
A(ax,(-7.95,2.7),(-7.95,5.1),c="#555",lw=2.0)
R(ax,-6.83,-4.80,5.2,5.4,"#555",ec="#222",z=3); R(ax,-6.83,-4.80,0.0,5.2,"#c9c3b2",ec="#222",lw=1.0,z=1,hatch="///"); T(ax,-5.8,2.6,"anteroom base:\nsteel frame +\nsolid skirt panels",8)
R(ax,-6.83,-4.83,5.4,8.5,"#f2e3b3",ec="#222",lw=2,z=2); T(ax,-5.85,7.4,"ANTEROOM\n2 x 2 m",9,"#7a5b00",w="bold"); R(ax,-6.83,-4.83,8.5,8.6,"#555",ec="#222",z=3)
R(ax,-4.80,-3.6,5.2,5.4,"#555",ec="#222",z=3); R(ax,-4.80,-3.6,5.4,8.5,"#ece5d4",ec="#222",lw=2,z=1); T(ax,-4.15,7.2,"CONTROL\nROOM",8)
ax.plot([-6.83,-6.83],[5.4,7.6],color="#c0392b",lw=6,zorder=6,solid_capstyle="butt"); ax.plot([-4.83,-4.83],[5.4,7.6],color="#c0392b",lw=6,zorder=6,solid_capstyle="butt")
A(ax,(-6.7,6.2),(-4.95,6.2),c="#c0392b",lw=2.2)
R(ax,-9.07,-8.95,0.0,10.8,"#555",ec="#222",z=2); T(ax,-9.5,3.0,"solid\nwest\nwall",7,"#444",ha="left")
ax.axhline(5.4,color="#999",lw=0.8,ls=":",zorder=0); T(ax,-9.55,5.55,"+5.4 m",7,"#777",ha="left"); ax.axhline(8.5,color="#999",lw=0.8,ls=":",zorder=0); T(ax,-9.55,8.65,"+8.5 m",7,"#777",ha="left")
fig.text(0.67,0.075,"The ground door is on the NORTH wall (not in this cut): the car has doors north and east.\n24 s loop (ground, ride up, upper, ride down), driven by scene time in seconds.",fontsize=8,color="#444",ha="left",va="top")
fig.savefig(OUT,facecolor="white"); print("wrote",OUT)
